{
  "items": [
    {
      "name": "Finset.sup_image₂_le",
      "module_name": "Mathlib.Data.Finset.NAry",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_3} {γ : Type u_5} {δ : Type u_7} [inst : DecidableEq γ] {f : α → β → γ} {s : Finset α}\n  {t : Finset β} [inst_1 : SemilatticeSup δ] [inst_2 : OrderBot δ] {g : γ → δ} {a : δ},\n  (Finset.image₂ f s t).sup g ≤ a ↔ ∀ x ∈ s, ∀ y ∈ t, g (f x y) ≤ a"
    },
    {
      "name": "Finset.sup'_image₂_le",
      "module_name": "Mathlib.Data.Finset.NAry",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_3} {γ : Type u_5} {δ : Type u_7} [inst : DecidableEq γ] {f : α → β → γ} {s : Finset α}\n  {t : Finset β} [inst_1 : SemilatticeSup δ] {g : γ → δ} {a : δ} (h : (Finset.image₂ f s t).Nonempty),\n  (Finset.image₂ f s t).sup' h g ≤ a ↔ ∀ x ∈ s, ∀ y ∈ t, g (f x y) ≤ a"
    },
    {
      "name": "sSup_image'",
      "module_name": "Mathlib.Order.CompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : SupSet α] {s : Set β} {f : β → α}, sSup (f '' s) = ⨆ a, f ↑a"
    },
    {
      "name": "Real.iSup_le",
      "module_name": "Mathlib.Data.Real.Archimedean",
      "kind": "theorem",
      "type": "∀ {ι : Sort u_1} {f : ι → ℝ} {a : ℝ}, (∀ (i : ι), f i ≤ a) → 0 ≤ a → ⨆ i, f i ≤ a"
    },
    {
      "name": "mem_upperBounds_image2",
      "module_name": "Mathlib.Order.Bounds.Image",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} {γ : Type w} [inst : Preorder α] [inst_1 : Preorder β] [inst_2 : Preorder γ] {f : α → β → γ}\n  {s : Set α} {t : Set β} {a : α} {b : β},\n  (∀ (b : β), Monotone (Function.swap f b)) →\n    (∀ (a : α), Monotone (f a)) → a ∈ upperBounds s → b ∈ upperBounds t → f a b ∈ upperBounds (Set.image2 f s t)"
    }
  ]
}

